import fs from "fs/promises";
import path from "path";

export interface Order {
  id: string;
  customerId: string;
  subscriptionDate: string;
  quantity: number;
  roastBatch: string;
  status: "Pending" | "Roasting" | "Shipped" | "Cancelled";
  total: number;
}
export interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  address: string;
  subscriptionStart: string;
  notes?: string;
}
const dataDir = path.resolve(process.cwd(), "data");
const ordersFile = path.join(dataDir, "orders.json");
const customersFile = path.join(dataDir, "customers.json");
async function ensureDataDir(): Promise<void> {
  await fs.mkdir(dataDir, { recursive: true });
}
export async function loadOrders(): Promise<Order[]> {
  await ensureDataDir();
  try {
    const raw = await fs.readFile(ordersFile, "utf8");
    return JSON.parse(raw) as Order[];
  } catch {
    return [];
  }
}
export async function saveOrders(orders: Order[]): Promise<void> {
  await ensureDataDir();
  await fs.writeFile(ordersFile, JSON.stringify(orders, null, 2), "utf8");
}
export async function loadCustomers(): Promise<Customer[]> {
  await ensureDataDir();
  try {
    const raw = await fs.readFile(customersFile, "utf8");
    return JSON.parse(raw) as Customer[];
  } catch {
    return [];
  }
}
export async function saveCustomers(customers: Customer[]): Promise<void> {
  await ensureDataDir();
  await fs.writeFile(customersFile, JSON.stringify(customers, null, 2), "utf8");
}
function isValidOrder(o: any): o is Order {
  return (
    typeof o.id === "string" &&
    typeof o.customerId === "string" &&
    typeof o.subscriptionDate === "string" &&
    typeof o.quantity === "number" &&
    typeof o.roastBatch === "string" &&
    ["Pending", "Roasting", "Shipped", "Cancelled"].includes(o.status) &&
    typeof o.total === "number"
  );
}
function isValidCustomer(c: any): c is Customer {
  return (
    typeof c.id === "string" &&
    typeof c.name === "string" &&
    typeof c.email === "string" &&
    typeof c.phone === "string" &&
    typeof c.address === "string" &&
    typeof c.subscriptionStart === "string"
  );
}
export async function queryOrders(
  search?: string,
  filters?: Partial<Order>
): Promise<Order[]> {
  const orders = await loadOrders();
  let result = orders;
  if (search) {
    const lower = search.toLowerCase();
    result = result.filter((o) =>
      Object.values(o).some(
        (v) => typeof v === "string" && v.toLowerCase().includes(lower)
      )
    );
  }
  if (filters) {
    result = result.filter((o) =>
      Object.entries(filters).every(
        ([k, v]) => (o as any)[k] === v
      )
    );
  }
  return result;
}
export async function queryCustomers(
  search?: string,
  filters?: Partial<Customer>
): Promise<Customer[]> {
  const customers = await loadCustomers();
  let result = customers;
  if (search) {
    const lower = search.toLowerCase();
    result = result.filter((c) =>
      Object.values(c).some(
        (v) => typeof v === "string" && v.toLowerCase().includes(lower)
      )
    );
  }
  if (filters) {
    result = result.filter((c) =>
      Object.entries(filters).every(
        ([k, v]) => (c as any)[k] === v
      )
    );
  }
  return result;
}
export async function updateOrder(
  id: string,
  changes: Partial<Order>
): Promise<Order | null> {
  const orders = await loadOrders();
  const idx = orders.findIndex((o) => o.id === id);
  if (idx === -1) return null;
  const updated = { ...orders[idx], ...changes };
  if (!isValidOrder(updated)) throw new Error("Invalid order data");
  orders[idx] = updated;
  await saveOrders(orders);
  return updated;
}
export async function updateCustomer(
  id: string,
  changes: Partial<Customer>
): Promise<Customer | null> {
  const customers = await loadCustomers();
  const idx = customers.findIndex((c) => c.id === id);
  if (idx === -1) return null;
  const updated = { ...customers[idx], ...changes };
  if (!isValidCustomer(updated)) throw new Error("Invalid customer data");
  customers[idx] = updated;
  await saveCustomers(customers);
  return updated;
}
export async function createOrder(order: Order): Promise<void> {
  if (!isValidOrder(order)) throw new Error("Invalid order data");
  const orders = await loadOrders();
  orders.push(order);
  await saveOrders(orders);
}
export async function createCustomer(customer: Customer): Promise<void> {
  if (!isValidCustomer(customer)) throw new Error("Invalid customer data");
  const customers = await loadCustomers();
  customers.push(customer);
  await saveCustomers(customers);
}

import { NextResponse } from "next/server";
import { queryOrders, createOrder, updateOrder } from "../../lib/store";
import type { Order } from "../../lib/store";

const VALID_STATUSES = ["Pending", "Roasting", "Shipped", "Cancelled"];

function isValidOrder(value: unknown): value is Order {
  if (typeof value !== "object" || value === null) return false;
  const o = value as Record<string, unknown>;
  return (
    typeof o.id === "string" &&
    typeof o.customerId === "string" &&
    typeof o.subscriptionDate === "string" &&
    typeof o.quantity === "number" &&
    typeof o.roastBatch === "string" &&
    typeof o.status === "string" &&
    VALID_STATUSES.includes(o.status) &&
    typeof o.total === "number"
  );
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const search = searchParams.get("search") ?? undefined;
  const status = searchParams.get("status");
  const from = searchParams.get("from");
  const to = searchParams.get("to");

  const filters: Partial<Order> = {};
  if (typeof status === "string" && VALID_STATUSES.includes(status)) {
    filters.status = status as Order["status"];
  }

  try {
    let orders = await queryOrders(search, Object.keys(filters).length > 0 ? filters : undefined);
    if (from) {
      const fromMs = new Date(from).getTime();
      if (!Number.isNaN(fromMs)) {
        orders = orders.filter((o) => new Date(o.subscriptionDate).getTime() >= fromMs);
      }
    }
    if (to) {
      const toMs = new Date(to).getTime();
      if (!Number.isNaN(toMs)) {
        orders = orders.filter((o) => new Date(o.subscriptionDate).getTime() <= toMs);
      }
    }
    return NextResponse.json(orders);
  } catch {
    return NextResponse.json({ error: "Unable to load orders." }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const body: unknown = await request.json();
    if (!isValidOrder(body)) {
      return NextResponse.json({ error: "Order details are incomplete or incorrect." }, { status: 400 });
    }
    await createOrder(body);
    return NextResponse.json(body, { status: 201 });
  } catch {
    return NextResponse.json({ error: "Unable to create order." }, { status: 400 });
  }
}

export async function PUT(request: Request) {
  try {
    const body: Record<string, unknown> = await request.json();
    const { id, ...changes } = body;
    if (typeof id !== "string") {
      return NextResponse.json({ error: "Order ID is missing." }, { status: 400 });
    }
    const updated = await updateOrder(id, changes as Partial<Order>);
    if (!updated) {
      return NextResponse.json({ error: "No order found with that ID." }, { status: 404 });
    }
    return NextResponse.json(updated);
  } catch {
    return NextResponse.json({ error: "Unable to update order." }, { status: 400 });
  }
}

