'use client';
import { useState, useEffect } from 'react';
import DataTable from '@/components/DataTable';
import { Order, Customer } from '@/lib/store';

type View = 'orders' | 'customers';

export default function Dashboard() {
  const [view, setView] = useState<View>('orders');
  const [orders, setOrders] = useState<Order[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState<string>('');
  const [orderStatusFilter, setOrderStatusFilter] = useState<string>('');

  const fetchOrders = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/orders');
      if (!res.ok) throw new Error('Failed to load orders');
      const data: Order[] = await res.json();
      setOrders(data);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchCustomers = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/customers');
      if (!res.ok) throw new Error('Failed to load customers');
      const data: Customer[] = await res.json();
      setCustomers(data);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (view === 'orders') fetchOrders();
    else fetchCustomers();
  }, [view]);

  const handleStatusChange = async (id: string, status: Order['status']) => {
    try {
      const res = await fetch('/api/orders', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, status }),
      });
      if (!res.ok) throw new Error('Update failed');
      await fetchOrders();
    } catch (e) {
      console.error(e);
    }
  };

  const filteredOrders = orders.filter((o) => {
    const matchesSearch =
      !search ||
      Object.values(o).some(
        (v) => typeof v === 'string' && v.toLowerCase().includes(search.toLowerCase())
      );
    const matchesStatus = !orderStatusFilter || o.status === orderStatusFilter;
    return matchesSearch && matchesStatus;
  });

  const filteredCustomers = customers.filter((c) => {
    if (!search) return true;
    return Object.values(c).some(
      (v) => typeof v === 'string' && v.toLowerCase().includes(search.toLowerCase())
    );
  });

  const exportCSV = (rows: any[], headers: string[]) => {
    const csvContent =
      headers.join(',') +
      '\n' +
      rows
        .map((row) =>
          headers
            .map((h) => {
              const v = row[h];
              const escaped = typeof v === 'string' ? `"${v.replace(/"/g, '""')}"` : v;
              return escaped;
            })
            .join(',')
        )
        .join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = view === 'orders' ? 'orders.csv' : 'customers.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const orderColumns = [
    { key: 'id', label: 'Order ID', sortable: true },
    { key: 'customerId', label: 'Customer', sortable: true },
    { key: 'subscriptionDate', label: 'Date', sortable: true },
    { key: 'quantity', label: 'Qty', sortable: true },
    { key: 'roastBatch', label: 'Batch', sortable: true },
    { key: 'status', label: 'Status', sortable: true },
    { key: 'total', label: 'Total ($)', sortable: true },
  ];

  const customerColumns = [
    { key: 'id', label: 'Customer ID', sortable: true },
    { key: 'name', label: 'Name', sortable: true },
    { key: 'email', label: 'Email', sortable: true },
    { key: 'phone', label: 'Phone', sortable: true },
    { key: 'address', label: 'Address', sortable: true },
    { key: 'subscriptionStart', label: 'Started', sortable: true },
  ];

  const orderRows = filteredOrders.map((o) => ({
    ...o,
    customerId: customers.find((c) => c.id === o.customerId)?.name || o.customerId,
  }));

  const customerRows = filteredCustomers;

  return (
    <main className="p-4">
      <header className="flex justify-between items-center mb-4">
        <h1 className="text-lg font-bold">Ember &amp; Oak – Subscription Dashboard</h1>
        <div className="flex gap-2 items-center">
          <input
            type="text"
            placeholder="Search…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="p-2 border rounded"
          />
          {view === 'orders' && (
            <select
              value={orderStatusFilter}
              onChange={(e) => setOrderStatusFilter(e.target.value)}
              className="p-2 border rounded"
            >
              <option value="">All statuses</option>
              <option value="Pending">Pending</option>
              <option value="Roasting">Roasting</option>
              <option value="Shipped">Shipped</option>
              <option value="Cancelled">Cancelled</option>
            </select>
          )}
          <button
            onClick={() =>
              view === 'orders'
                ? exportCSV(orderRows, orderColumns.map((c) => c.key))
                : exportCSV(customerRows, customerColumns.map((c) => c.key))
            }
            className="bg-primary text-white p-2 rounded transition"
          >
            Export CSV
          </button>
        </div>
      </header>

      <nav className="flex gap-4 mb-4">
        <button
          onClick={() => setView('orders')}
          className={`p-2 rounded ${view === 'orders' ? 'bg-primary text-white' : 'bg-muted'}`}
        >
          Orders
        </button>
        <button
          onClick={() => setView('customers')}
          className={`p-2 rounded ${view === 'customers' ? 'bg-primary text-white' : 'bg-muted'}`}
        >
          Customers
        </button>
      </nav>

      {error && <p className="text-red-600 m-2">{error}</p>}
      {loading && <p className="m-2">Loading…</p>}

      {view === 'orders' && (
        <DataTable
          columns={orderColumns}
          rows={orderRows}
          loading={loading}
          emptyMessage="No orders found for the current criteria."
          onRowUpdate={async (id, changes) => {
            if (changes.status) {
              await handleStatusChange(id, changes.status as Order['status']);
            }
          }}
        />
      )}

      {view === 'customers' && (
        <DataTable
          columns={customerColumns}
          rows={customerRows}
          loading={loading}
          emptyMessage="No customers match your search."
        />
      )}
    </main>
  );
}

'use client';
import { useState } from 'react';

export interface Column {
  key: string;
  label: string;
  sortable?: boolean;
}

interface DataTableProps<T extends { id: string }> {
  columns: Column[];
  rows: T[];
  onRowUpdate?: (id: string, changes: Partial<T>) => Promise<void>;
  emptyMessage: string;
  loading: boolean;
}

export default function DataTable<T extends { id: string }>({
  columns,
  rows,
  onRowUpdate,
  emptyMessage,
  loading,
}: DataTableProps<T>) {
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [asc, setAsc] = useState(true);

  const handleHeaderClick = (col: Column) => {
    if (!col.sortable) return;
    if (sortKey === col.key) {
      setAsc(!asc);
    } else {
      setSortKey(col.key);
      setAsc(true);
    }
  };

  const sortedRows = () => {
    if (!sortKey) return rows;
    const copy = [...rows];
    copy.sort((a, b) => {
      const av = (a as any)[sortKey];
      const bv = (b as any)[sortKey];
      if (typeof av === 'number' && typeof bv === 'number') {
        return asc ? av - bv : bv - av;
      }
      const as = String(av).toLowerCase();
      const bs = String(bv).toLowerCase();
      if (as < bs) return asc ? -1 : 1;
      if (as > bs) return asc ? 1 : -1;
      return 0;
    });
    return copy;
  };

  const handleStatusChange = async (id: string, value: string) => {
    if (!onRowUpdate) return;
    await onRowUpdate(id, { status: value } as Partial<T>);
  };

  if (loading) {
    return <div className="p-2 text-muted">Loading…</div>;
  }

  if (rows.length === 0) {
    return <div className="p-2 text-muted">{emptyMessage}</div>;
  }

  return (
    <table className="table">
      <thead>
        <tr>
          {columns.map((col) => (
            <th
              key={col.key}
              onClick={() => handleHeaderClick(col)}
              className={col.sortable ? 'cursor-pointer' : undefined}
            >
              {col.label}
              {col.sortable && sortKey === col.key && (asc ? ' ▲' : ' ▼')}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {sortedRows().map((row) => (
          <tr key={row.id}>
            {columns.map((col) => (
              <td key={col.key}>
                {col.key === 'status' && onRowUpdate ? (
                  <select
                    value={(row as any)[col.key]}
                    onChange={(e) => handleStatusChange(row.id, e.target.value)}
                    className="p-1 border rounded"
                  >
                    <option value="Pending">Pending</option>
                    <option value="Roasting">Roasting</option>
                    <option value="Shipped">Shipped</option>
                    <option value="Cancelled">Cancelled</option>
                  </select>
                ) : (
                  String((row as any)[col.key])
                )}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}
